-- 413: Original BrillaPrep WASSCE Integrated Science beta questions, part 1 of 8 (sprint 1 batch 001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_413_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_413_guard;
INSERT INTO _migration_413_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_eco_b001_001' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_eco' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following is an abiotic component of a pond ecosystem?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Algae","B. Tadpoles","C. Sunlight","D. Pond snails"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Abiotic factors are the non-living parts of an ecosystem, such as sunlight, water and temperature. Algae, tadpoles and pond snails are all living (biotic) components of the pond.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_eco_b001_001' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_413_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_eco_b001_002' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_eco' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In a food chain, the organisms that make their own food by photosynthesis are called:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Producers","B. Herbivores","C. Decomposers","D. Secondary consumers"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Producers (green plants and algae) make their own food by photosynthesis. Herbivores and secondary consumers eat other organisms, and decomposers feed on dead organic matter.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_eco_b001_002' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_413_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_eco_b001_003' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_eco' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The place where an organism lives and obtains its food and shelter is its:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Niche","B. Population","C. Biome","D. Habitat"]' AND q.correct_answer IS 'D' AND q.explanation IS 'A habitat is the physical place where an organism lives and finds food and shelter. A niche is the organism’s role in the ecosystem, and a population is a group of one species.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_eco_b001_003' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_413_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_eco_b001_004' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_eco' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which group of organisms breaks down dead plants and animals, returning nutrients to the soil?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Producers","B. Decomposers","C. Primary consumers","D. Predators"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Decomposers (bacteria and fungi) break down dead organisms, releasing nutrients such as nitrates into the soil for producers to use. Predators and primary consumers do not recycle nutrients.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_eco_b001_004' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_413_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_eco_b001_005' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_eco' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Consider the food chain: maize → grasshopper → lizard → hawk. The secondary consumer in this chain is the:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Maize","B. Grasshopper","C. Lizard","D. Hawk"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Maize is the producer, the grasshopper eating it is the primary consumer, the lizard eating the grasshopper is the secondary consumer, and the hawk is the tertiary consumer.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_eco_b001_005' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_413_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_eco_b001_006' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_eco' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In an energy pyramid for a savanna ecosystem, the greatest amount of energy is found at the level of the:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Producers","B. Top carnivores","C. Primary consumers","D. Secondary consumers"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Only about 10% of the energy passes from one trophic level to the next; the rest is lost as heat. Producers trap all the incoming solar energy, so they hold the greatest amount.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_eco_b001_006' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
